namespace {
void check(bool b,const char*s){if(!b)throw std::runtime_error(s);}
template<class T>T*child(QObject&o,const char*name){auto*v=o.findChild<T*>(name);check(v,name);return v;}
void events(){QApplication::processEvents();QThread::msleep(2);}
void syntheticHeaderFixture(const QString&path){
    QByteArray header(4096,'\0'),payload(32,'\0');header.replace(0,8,QByteArray("CAPDDR2\0",8));auto store=[&](unsigned at,std::uint64_t value,unsigned count=4){for(unsigned j=0;j<count;++j)header[int(at+j)]=char(value>>(8*j));};store(8,2);store(12,4096);store(16,32);store(20,2);store(24,5000);store(28,50000000);store(32,1);store(36,1);store(40,32);store(48,64);store(60,1);store(80,0x50301);store(84,5000000);store(96,vibration::crc32(reinterpret_cast<const std::uint8_t*>(payload.constData()),payload.size()));store(100,vibration::crc32(reinterpret_cast<const std::uint8_t*>(header.constData()),128));QFile f(path);check(f.open(QIODevice::WriteOnly),"synthetic header fixture open");check(f.write(header)==header.size()&&f.write(payload)==payload.size(),"synthetic header fixture bytes");
}
}
int main(int argc,char**argv){QApplication app(argc,argv);qa::configureFonts(app);try{
    QTemporaryDir dir;CandidatePanel panel;panel.setStorageRoot(dir.path());panel.resize(1024,600);panel.show();check(child<QComboBox>(panel,"candidateBackend")->currentIndex()!=0,"ordinary workflow has a verified automatic compute selection");check(child<QCheckBox>(panel,"candidateMechanicalConfirmed")->isVisible(),"current source confirmation is directly available without advanced settings");
    const auto emptyText=child<QTextBrowser>(panel,"detectionEvidence")->toPlainText();check(emptyText.contains(QStringLiteral("四种工况"))&&emptyText.contains(QStringLiteral("参考样本库"))&&emptyText.contains(QStringLiteral("训练模型"))&&!emptyText.contains(QStringLiteral("建立正常基线")),"empty detection page leads to four-class reference workflow");check(child<QLabel>(panel,"detectionProfileSummary")->text().isEmpty(),"default model summary does not duplicate the first-use instruction");
    panel.showReferenceLibrary();for(unsigned i=0;i<20;++i)events();auto*dialog=child<QDialog>(panel,"referenceLibraryDialog");check(dialog->isVisible()&&dialog->width()<=1024&&dialog->height()<=600,"reference dialog fits target display");check(!child<QWidget>(panel,"referenceLibraryAdvanced")->isVisible()&&!child<QComboBox>(panel,"referenceBackend")->isVisible(),"ordinary library keeps engineering and import-export controls folded");check(child<QLabel>(panel,"referenceClassCounts")->text().contains(QStringLiteral("正常 0")),"four actual file counts visible");check(!child<QPushButton>(panel,"buildReferenceModel")->isEnabled(),"cannot train absent four classes");auto*table=child<QTreeWidget>(panel,"referenceLibraryList");check(table->columnCount()==4&&table->headerItem()->text(1).contains(QStringLiteral("目录"))&&table->headerItem()->text(2).contains(QStringLiteral("训练窗")),"training table exposes source directories and actual extracted window counts");
    // Provenance-formatting fixtures only: no BIN is created or admitted here.
    const auto namedA=(dir.path()+QStringLiteral("/松动/1200rpm_轻度/data.BIN")).toUtf8().toStdString(),namedB=(dir.path()+QStringLiteral("/松动/1200rpm_重度/data.BIN")).toUtf8().toStdString();const auto sourceA=referenceSourceName(dir.path(),namedA),sourceB=referenceSourceName(dir.path(),namedB);check(sourceA!=sourceB&&sourceA.contains(QStringLiteral("轻度"))&&sourceB.contains(QStringLiteral("重度")),"same data.BIN names remain distinguishable by relative directories");vibration::ReferenceSample metadataOnly;vibration::CandidateWindow one,two;one.rpm_min=1180;one.rpm_max=1220;two.rpm_min=1980;two.rpm_max=2020;metadataOnly.windows={one,two};check(referenceMeasuredRpm(metadataOnly)==QStringLiteral("1180.0–2020.0"),"legacy metadata formatter preserves actual min/max independently of the supervised UI");
    check(!panel.addReferenceFile(dir.path()+"/missing.BIN","normal"),"operator label never supplies mechanical confirmation");check(child<QLabel>(panel,"referenceLibraryStatus")->text().contains(QStringLiteral("来源确认")),"missing source confirmation has explicit recovery");child<QComboBox>(panel,"candidateBackend")->setCurrentIndex(2);child<QCheckBox>(panel,"referenceMechanicalConfirmed")->setChecked(true);check(!child<QCheckBox>(panel,"candidateMechanicalConfirmed")->isChecked(),"reference-source confirmation does not assert source of current unknown input");check(!child<QCheckBox>(panel,"candidateNormalConfirmed")->isChecked(),"mechanical or operator label never confirms normal condition");
    check(!panel.addReferenceFile(dir.path()+"/missing.BIN","unlabeled"),"unlabeled file cannot enter reference library");check(!panel.addReferenceFile(dir.path()+"/missing.BIN","normal"),"missing or nonordinary BIN rejected immediately");
    const auto bad=dir.path()+"/invalid.BIN";QFile f(bad);check(f.open(QIODevice::WriteOnly),"prepare invalid mathematical bytes");f.write("mathematical invalid BIN fixture");f.close();check(panel.addReferenceFile(bad,"normal"),"actual file validation queued asynchronously");unsigned ticks=0;QElapsedTimer elapsed;elapsed.start();while(!panel.property("referenceLibraryStatus").toString().contains(QStringLiteral("未加入"))&&elapsed.elapsed()<10000){events();++ticks;}check(panel.property("referenceLibraryStatus").toString().contains(QStringLiteral("未加入")),"asynchronous CRC/source/label failure remains visible");check(panel.property("referenceFileCount").toInt()==0&&ticks>0,"failure never adds phantom sample and completes through the event loop");check(!QFile::exists(dir.path()+"/.vibration-workbench/reference-library.json")&&!QFile::exists(dir.path()+"/.vibration-workbench/supervised-library.json"),"rejected fixture never creates a mechanical training library");
    // The SD chooser hands off an explicit file selection before the batch
    // source declaration. Retain that selection only while this dialog is open.
    QTemporaryDir deferredRoot;CandidatePanel deferred;deferred.setStorageRoot(deferredRoot.path());deferred.showReferenceLibrary();events();
    check(deferred.addReferenceFile(bad,"normal")&&deferred.property("referenceAwaitingConfirmation").toBool(),"chosen path is retained while source confirmation is pending");
    check(!child<QCheckBox>(deferred,"referenceMechanicalConfirmed")->isChecked()&&deferred.property("referenceFileCount").toInt()==0,"saved class label never supplies mechanical source declaration");
    child<QDialog>(deferred,"referenceLibraryDialog")->reject();check(!deferred.property("referenceAwaitingConfirmation").toBool(),"closing cancels the unconfirmed selection");
    child<QCheckBox>(deferred,"referenceMechanicalConfirmed")->setChecked(true);for(unsigned i=0;i<50;++i)events();
    check(deferred.property("referenceFileCount").toInt()==0&&deferred.property("referenceLibraryStatus").toString().contains(QStringLiteral("已取消")),"later source confirmation cannot resurrect a cancelled file selection");
    child<QCheckBox>(deferred,"referenceMechanicalConfirmed")->setChecked(false);deferred.showReferenceLibrary();events();check(deferred.addReferenceFile(bad,"normal"),"second explicit selection retained");child<QCheckBox>(deferred,"referenceMechanicalConfirmed")->setChecked(true);elapsed.restart();while(!deferred.property("referenceLibraryStatus").toString().contains(QStringLiteral("未加入"))&&elapsed.elapsed()<10000)events();
    check(!deferred.property("referenceAwaitingConfirmation").toBool()&&deferred.property("referenceLibraryStatus").toString().contains(QStringLiteral("未加入"))&&deferred.property("referenceFileCount").toInt()==0,"source confirmation automatically starts the preserved selection's genuine worker validation");child<QDialog>(deferred,"referenceLibraryDialog")->reject();
    const auto synthetic=dir.path()+"/synthetic-only.BIN";syntheticHeaderFixture(synthetic);QString labelError;check(saveRecordLabel(synthetic,RecordLabel::Normal,"mathematical-only",nullptr,&labelError),"synthetic record can be organized without being training eligible");check(panel.addReferenceFile(synthetic,"normal"),"synthetic source rejection runs in worker");elapsed.restart();while(!panel.property("referenceLibraryStatus").toString().contains(QStringLiteral("合成记录"))&&elapsed.elapsed()<10000)events();check(panel.property("referenceLibraryStatus").toString().contains(QStringLiteral("合成记录"))&&panel.property("referenceFileCount").toInt()==0,"operator normal tag and source checkbox cannot admit a synthetic fixture");
    QTemporaryDir previousRoot;check(QDir().mkpath(previousRoot.path()+"/.vibration-workbench"),"prepare previous library root");const auto previousPath=previousRoot.path()+"/.vibration-workbench/reference-library.json";const QByteArray previousBytes("{\"schema\":\"mathematical-invalid-library-preservation-fixture\"}");QFile previous(previousPath);check(previous.open(QIODevice::WriteOnly)&&previous.write(previousBytes)==previousBytes.size(),"write preservation fixture");previous.close();CandidatePanel restarted;restarted.setStorageRoot(previousRoot.path());child<QComboBox>(restarted,"referenceBackend")->setCurrentIndex(2);child<QCheckBox>(restarted,"referenceMechanicalConfirmed")->setChecked(true);check(restarted.addReferenceFile(bad,"normal"),"restart queues verification of previous library before new entry");elapsed.restart();while(!restarted.property("referenceLibraryStatus").toString().contains(QStringLiteral("参考库格式无效"))&&elapsed.elapsed()<10000)events();check(restarted.property("referenceLibraryStatus").toString().contains(QStringLiteral("参考库格式无效")),"previous invalid library blocks implicit overwrite");check(previous.open(QIODevice::ReadOnly)&&previous.readAll()==previousBytes,"existing unloaded manifest is preserved exactly");previous.close();
    check(panel.addReferenceFile(synthetic,"normal"),"enqueue cancellation fixture");child<QCheckBox>(panel,"referenceMechanicalConfirmed")->setChecked(false);elapsed.restart();while(!panel.property("referenceLibraryStatus").toString().contains(QStringLiteral("旧参考任务已取消"))&&elapsed.elapsed()<10000)events();check(panel.property("referenceLibraryStatus").toString().contains(QStringLiteral("旧参考任务已取消"))&&panel.property("referenceFileCount").toInt()==0,"late worker cannot publish after source confirmation changes");
    if(argc>1)check(dialog->grab().save(QString::fromUtf8(argv[1])),"reference library screenshot");
    std::cout<<"PASS: reference library target-display UI, four counts, source/normal separation, absent-label/path/invalid-BIN rejection, asynchronous failure without mechanical fixture ingestion. No machine data or board accessed.\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
